// src/core/tensor_core.zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;
const meta = @import("meta.zig");
const c = @cImport({
    @cInclude("math.h");
    @cInclude("complex.h");
    @cInclude("immintrin.h");
    @cInclude("fftw3.h");
});

pub const DType = enum { f64, f32, i64, i32, c64, c32 };

pub const Shape = []const usize;

pub fn totalElements(shape: Shape) usize {
    var total: usize = 1;
    for (shape) |dim| {
        total *= dim;
    }
    return total;
}

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,
    requires_grad: bool = false,
    grad: ?*Tensor = null,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        const total = totalElements(shape);
        const data_type_size: usize = switch (dtype) {
            .f64 => @sizeOf(f64),
            .f32 => @sizeOf(f32),
            .i64 => @sizeOf(i64),
            .i32 => @sizeOf(i32),
            .c64 => @sizeOf(complex(f64)),
            .c32 => @sizeOf(complex(f32)),
        };
        const data = try allocator.alloc(u8, total * data_type_size);
        @memset(data, 0);
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .is_view = false,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        if (self.grad) |g| g.deinit();
    }

    pub fn view(self: Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        if (totalElements(self.shape) != totalElements(new_shape)) {
            return error.ShapeMismatch;
        }
        const shape_copy = try allocator.dupe(usize, new_shape);
        var strides = try allocator.alloc(usize, new_shape.len);
        if (new_shape.len > 0) {
            strides[new_shape.len - 1] = 1;
            var i: usize = new_shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
            .requires_grad = self.requires_grad,
            .grad = self.grad,
        };
    }

    pub fn reshape(self: *Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        return self.view(allocator, new_shape);
    }

    pub fn get(self: *const Tensor, indices: []usize) f64 {
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            idx += i * self.strides[dim];
        }
        return @as(*const f64, @alignCast(@ptrCast(&self.data[idx * @sizeOf(f64)]))).*;
    }

    pub fn set(self: *Tensor, indices: []usize, value: f64) void {
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            idx += i * self.strides[dim];
        }
        @as(*f64, @alignCast(@ptrCast(&self.data[idx * @sizeOf(f64)]))).* = value;
    }

    pub fn add(self: *Tensor, other: *const Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, other.shape) or self.shape.len != result.shape.len or !std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |flat_idx| {
            const self_val = self.get(&.{flat_idx}) orelse 0.0;
            const other_val = other.get(&.{flat_idx}) orelse 0.0;
            try result.set(&.{flat_idx}, self_val + other_val);
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, other.shape) or self.shape.len != result.shape.len or !std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |flat_idx| {
            const self_val = self.get(&.{flat_idx}) orelse 0.0;
            const other_val = other.get(&.{flat_idx}) orelse 0.0;
            try result.set(&.{flat_idx}, self_val * other_val);
        }
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0] or result.shape.len != 2 or result.shape[0] != self.shape[0] or result.shape[1] != other.shape[1]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        @memset(result.data, 0);
        const self_data = @as([*]const f64, @alignCast(@ptrCast(self.data.ptr)));
        const other_data = @as([*]const f64, @alignCast(@ptrCast(other.data.ptr)));
        const result_data = @as([*]f64, @alignCast(@ptrCast(result.data.ptr)));
        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f64 = 0.0;
                for (0..k) |l| {
                    sum += self_data[i * k + l] * other_data[l * n + j];
                }
                result_data[i * n + j] = sum;
            }
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator, result: *Tensor) !void {
        if (self.shape.len != 2 or result.shape.len != 2 or self.shape[0] != result.shape[1] or self.shape[1] != result.shape[0]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = self.shape[1];
        @memset(result.data, 0);
        const self_data = @as([*]const f64, @alignCast(@ptrCast(self.data.ptr)));
        const result_data = @as([*]f64, @alignCast(@ptrCast(result.data.ptr)));
        for (0..m) |i| {
            for (0..n) |j| {
                result_data[j * m + i] = self_data[i * n + j];
            }
        }
    }

    pub fn sum(self: *const Tensor, axis: ?usize, allocator: Allocator, result_shape: Shape) !Tensor {
        var new_shape = try allocator.dupe(usize, self.shape);
        if (axis) |a| {
            new_shape[a] = 1;
        }
        var result = try Tensor.init(allocator, new_shape, self.dtype);
        // Implementation for sum reduction along axis
        // For brevity, assume axis = null for total sum
        var total: f64 = 0.0;
        const total_elements = totalElements(self.shape);
        for (0..total_elements) |i| {
            total += self.get(&.{i}) orelse 0.0;
        }
        const flat_idx = 0;
        try result.set(&.{flat_idx}, total);
        return result;
    }

    pub fn mean(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        const sum_tensor = try self.sum(axis, allocator, self.shape);
        const total = @as(f64, @floatFromInt(totalElements(self.shape)));
        // Divide sum by total
        // Implementation similar to mul but with scalar
        return sum_tensor;
    }

    pub fn fft(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 1) {
            return error.InvalidShapeForFFT;
        }
        const n = self.shape[0];
        var plan = c.fftw_plan_dft_r2c_1d(
            @intCast(n),
            @as([*c]c_double, @alignCast(@ptrCast(self.data.ptr))),
            @as([*c]c_fftw_complex, @ptrCast(allocator.alloc(c_fftw_complex, (n / 2) + 1))),
            c.FFTW_ESTIMATE,
        );
        c.fftw_execute(plan);
        c.fftw_destroy_plan(plan);
        // Return complex tensor
        const complex_shape = &[_]usize{ (n / 2) + 1, 2 };
        var complex_tensor = try Tensor.init(allocator, complex_shape, .c64);
        // Copy data
        return complex_tensor;
    }

    pub fn ifft(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 2 or self.shape[1] != 2) {
            return error.InvalidShapeForIFFT;
        }
        const n_complex = self.shape[0];
        const n = 2 * (n_complex - 1);
        var plan = c.fftw_plan_dft_c2r_1d(
            @intCast(n),
            @as([*c]c_fftw_complex, @alignCast(@ptrCast(self.data.ptr))),
            @as([*c]c_double, @ptrCast(allocator.alloc(c_double, n))),
            c.FFTW_ESTIMATE,
        );
        c.fftw_execute(plan);
        c.fftw_destroy_plan(plan);
        const real_shape = &[_]usize{n};
        var real_tensor = try Tensor.init(allocator, real_shape, .f64);
        // Copy data
        return real_tensor;
    }

    pub fn conv2d(self: *const Tensor, kernel: *const Tensor, padding: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 3 or kernel.shape.len != 3 or self.shape[1] != kernel.shape[1]) {
            return error.InvalidShapeForConv;
        }
        const batch = self.shape[0];
        const in_channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3] orelse in_h; // Assume square
        const out_channels = kernel.shape[0];
        const k_h = kernel.shape[2];
        const k_w = kernel.shape[3] orelse k_h;
        const out_h = ((in_h + 2 * padding - k_h) / stride) + 1;
        const out_w = ((in_w + 2 * padding - k_w) / stride) + 1;
        const out_shape = &[_]usize{ batch, out_channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        @memset(result.data, 0);
        // Convolution loop
        for (0..batch) |b| {
            for (0..out_channels) |oc| {
                for (0..out_h) |oh| {
                    for (0..out_w) |ow| {
                        var sum: f64 = 0.0;
                        const start_h = stride * oh - padding;
                        const start_w = stride * ow - padding;
                        for (0..k_h) |kh| {
                            const ih = start_h + kh;
                            if (ih < 0 or ih >= in_h) continue;
                            for (0..k_w) |kw| {
                                const iw = start_w + kw;
                                if (iw < 0 or iw >= in_w) continue;
                                for (0..in_channels) |ic| {
                                    const self_idx = &.{ b, ic, ih, iw };
                                    const kernel_idx = &.{ oc, ic, kh, kw };
                                    sum += (self.get(self_idx) orelse 0.0) * (kernel.get(kernel_idx) orelse 0.0);
                                }
                            }
                        }
                        const result_idx = &.{ b, oc, oh, ow };
                        try result.set(result_idx, sum);
                    }
                }
            }
        }
        return result;
    }

    pub fn maxpool2d(self: *const Tensor, kernel_size: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 3) {
            return error.InvalidShapeForPool;
        }
        const batch = self.shape[0];
        const channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3] orelse in_h;
        const out_h = (in_h - kernel_size) / stride + 1;
        const out_w = (in_w - kernel_size) / stride + 1;
        const out_shape = &[_]usize{ batch, channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        @memset(result.data, 0);
        // Maxpool loop
        for (0..batch) |b| {
            for (0..channels) |c| {
                for (0..out_h) |oh| {
                    for (0..out_w) |ow| {
                        var max_val: f64 = -math.inf(f64);
                        for (0..kernel_size) |kh| {
                            const ih = stride * oh + kh;
                            if (ih >= in_h) break;
                            for (0..kernel_size) |kw| {
                                const iw = stride * ow + kw;
                                if (iw >= in_w) break;
                                const idx = &.{ b, c, ih, iw };
                                const val = self.get(idx) orelse -math.inf(f64);
                                if (val > max_val) max_val = val;
                            }
                        }
                        const result_idx = &.{ b, c, oh, ow };
                        try result.set(result_idx, max_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn relu(self: *Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |flat_idx| {
            const val = self.get(&.{flat_idx}) orelse 0.0;
            try result.set(&.{flat_idx}, math.max(f64, val, 0.0));
        }
    }

    pub fn softmax(self: *const Tensor, axis: usize, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        var max_val: f64 = -math.inf(f64);
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            if (val > max_val) max_val = val;
        }
        var sum_exp: f64 = 0.0;
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            sum_exp += math.exp(val - max_val);
        }
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            try result.set(&.{i}, math.exp(val - max_val) / sum_exp);
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            self.grad = Tensor.init(self.allocator, self.shape, self.dtype) catch return;
        }
        // Simple add for backward, in real impl chain rule
        self.grad.?.add(grad_output, self.grad.?, {}) catch return;
    }

    pub fn zero_grad(self: *Tensor) void {
        if (self.grad) |g| {
            @memset(g.data, 0);
        }
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape, self.dtype);
        @memcpy(cloned.data, self.data);
        return cloned;
    }

    pub fn to_device(self: *Tensor, device: []const u8) !void {
        _ = device; // Stub for CPU/GPU switch
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        try writer.writeAll(std.mem.asBytes(self.data));
    }

    pub fn load(allocator: Allocator, path: []const u8, shape: Shape, dtype: DType) !Tensor {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const total = totalElements(shape);
        const data = try allocator.alloc(f64, total);
        _ = try file.readAll(std.mem.asBytes(data));
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
        };
    }

    test "tensor init and basic ops" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape = &[_]usize{ 2, 3 };
        var tensor = try Tensor.init(allocator, shape, .f64);
        defer tensor.deinit();
        try tensor.set(&.{0, 0}, 1.0);
        try tensor.set(&.{1, 2}, 6.0);
        try testing.expectEqual(f64, 1.0, tensor.get(&.{0, 0}).?);
    }

    test "matmul" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape_a = &[_]usize{ 2, 3 };
        const shape_b = &[_]usize{ 3, 4 };
        const shape_c = &[_]usize{ 2, 4 };
        var a = try Tensor.init(allocator, shape_a, .f64);
        defer a.deinit();
        var b = try Tensor.init(allocator, shape_b, .f64);
        defer b.deinit();
        var c = try Tensor.init(allocator, shape_c, .f64);
        defer c.deinit();
        // Fill a and b with test data
        try a.set(&.{0, 0}, 1.0); try a.set(&.{0, 1}, 2.0); try a.set(&.{0, 2}, 3.0);
        try a.set(&.{1, 0}, 4.0); try a.set(&.{1, 1}, 5.0); try a.set(&.{1, 2}, 6.0);
        try b.set(&.{0, 0}, 7.0); try b.set(&.{0, 1}, 8.0); try b.set(&.{0, 2}, 9.0); try b.set(&.{0, 3}, 10.0);
        try b.set(&.{1, 0}, 11.0); try b.set(&.{1, 1}, 12.0); try b.set(&.{1, 2}, 13.0); try b.set(&.{1, 3}, 14.0);
        try b.set(&.{2, 0}, 15.0); try b.set(&.{2, 1}, 16.0); try b.set(&.{2, 2}, 17.0); try b.set(&.{2, 3}, 18.0);
        try a.matmul(&b, &c);
        try testing.expectEqual(f64, 140.0, c.get(&.{0, 0}).?);
        try testing.expectEqual(f64, 152.0, c.get(&.{0, 1}).?);
    }

    test "conv2d basic" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape_in = &[_]usize{ 1, 1, 5, 5 };
        const shape_k = &[_]usize{ 1, 1, 3, 3 };
        var input = try Tensor.init(allocator, shape_in, .f64);
        defer input.deinit();
        var kernel = try Tensor.init(allocator, shape_k, .f64);
        defer kernel.deinit();
        // Fill test data
        for (0..25) |i| {
            try input.set(&.{0, 0, @intCast(i / 5), @intCast(i % 5)}, @as(f64, @floatFromInt(i + 1)));
        }
        for (0..9) |i| {
            try kernel.set(&.{0, 0, @intCast(i / 3), @intCast(i % 3)}, 1.0);
        }
        const out = try input.conv2d(&kernel, 0, 1, allocator);
        defer out.deinit();
        try testing.expectEqual(f64, 25.0 * 1.0, out.get(&.{0, 0, 0, 0}).?); // Approximate
    }

    test "relu activation" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape = &[_]usize{ 3 };
        var input = try Tensor.init(allocator, shape, .f64);
        defer input.deinit();
        var output = try Tensor.init(allocator, shape, .f64);
        defer output.deinit();
        try input.set(&.{0}, -1.0);
        try input.set(&.{1}, 0.0);
        try input.set(&.{2}, 2.0);
        try input.relu(&output);
        try testing.expectEqual(f64, 0.0, output.get(&.{0}).?);
        try testing.expectEqual(f64, 0.0, output.get(&.{1}).?);
        try testing.expectEqual(f64, 2.0, output.get(&.{2}).?);
    }

    test "softmax" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape = &[_]usize{ 3 };
        var input = try Tensor.init(allocator, shape, .f64);
        defer input.deinit();
        var output = try Tensor.init(allocator, shape, .f64);
        defer output.deinit();
        try input.set(&.{0}, 1.0);
        try input.set(&.{1}, 2.0);
        try input.set(&.{2}, 3.0);
        try input.softmax(0, &output);
        const e1 = math.exp(1.0); const e2 = math.exp(2.0); const e3 = math.exp(3.0);
        const sum = e1 + e2 + e3;
        try testing.expectApproxEqAbs(f64, e1 / sum, output.get(&.{0}).?, 1e-6);
        try testing.expectApproxEqAbs(f64, e3 / sum, output.get(&.{2}).?, 1e-6);
    }

    test "backward propagation stub" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape = &[_]usize{ 1 };
        var tensor = try Tensor.init(allocator, shape, .f64);
        tensor.requires_grad = true;
        defer tensor.deinit();
        var grad_out = try Tensor.init(allocator, shape, .f64);
        defer grad_out.deinit();
        try grad_out.set(&.{0}, 1.0);
        tensor.backward(&grad_out);
        if (tensor.grad) |g| {
            try testing.expectEqual(f64, 1.0, g.get(&.{0}).?);
        }
    }

    pub fn adam_update(self: *Tensor, m: *Tensor, v: *Tensor, beta1: f64, beta2: f64, lr: f64, t: usize, eps: f64) void {
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const grad_val = if (self.grad) |g| g.get(&.{i}) orelse 0.0 else 0.0;
            const m_old = m.get(&.{i}) orelse 0.0;
            const v_old = v.get(&.{i}) orelse 0.0;
            const m_new = beta1 * m_old + (1.0 - beta1) * grad_val;
            const v_new = beta2 * v_old + (1.0 - beta2) * grad_val * grad_val;
            try m.set(&.{i}, m_new);
            try v.set(&.{i}, v_new);
            const m_hat = m_new / (1.0 - math.pow(f64, beta1, @floatFromInt(t)));
            const v_hat = v_new / (1.0 - math.pow(f64, beta2, @floatFromInt(t)));
            const update = -lr * m_hat / (math.sqrt(v_hat) + eps);
            const old_val = self.get(&.{i}) orelse 0.0;
            try self.set(&.{i}, old_val + update);
        }
    }

    pub fn spectral_norm(self: *Tensor, allocator: Allocator, num_power_iters: usize) !f64 {
        var u = try self.clone(allocator);
        defer u.deinit();
        const total = totalElements(self.shape);
        for (0..num_power_iters) |_|
        {
            var ut = try u.transpose(allocator, self); // Assume square
            defer ut.deinit();
            var v = try Tensor.init(allocator, self.shape, .f64);
            defer v.deinit();
            try self.matmul(&u, &v); // A u
            u = v;
        }
        var u_norm_sq: f64 = 0.0;
        for (0..total) |i| {
            const val = u.get(&.{i}) orelse 0.0;
            u_norm_sq += val * val;
        }
        return math.sqrt(u_norm_sq);
    }

    pub fn dropout(self: *Tensor, p: f64, rng: *DefaultPrng, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var seed = rng.random().int(usize);
        var prng = DefaultPrng.init(seed);
        const rand = prng.random();
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            if (rand.float(f64) < p) {
                try result.set(&.{i}, 0.0);
            } else {
                try result.set(&.{i}, val / (1.0 - p));
            }
        }
    }

    pub fn layer_norm(self: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape) or !std.mem.eql(usize, self.shape, gamma.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var mean: f64 = 0.0;
        var var_sum: f64 = 0.0;
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            mean += val;
        }
        mean /= @as(f64, @floatFromInt(total));
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            var_sum += (val - mean) * (val - mean);
        }
        const variance = var_sum / @as(f64, @floatFromInt(total)) + eps;
        const std = math.sqrt(variance);
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            const normalized = (val - mean) / std;
            const gamma_val = gamma.get(&.{i}) orelse 1.0;
            const beta_val = beta.get(&.{i}) orelse 0.0;
            try result.set(&.{i}, gamma_val * normalized + beta_val);
        }
    }

    pub fn gelu(self: *Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const x = self.get(&.{i}) orelse 0.0;
            const gelu_approx = x * (1.0 / (1.0 + math.exp(-1.6732632423543772848170429916717 * x * x)));
            try result.set(&.{i}, gelu_approx);
        }
    }

    pub fn batch_norm(self: *Tensor, running_mean: *Tensor, running_var: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, training: bool, momentum: f64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const batch_size = self.shape[0];
        const channels = self.shape[1];
        const spatial = totalElements(self.shape) / (batch_size * channels);
        var mean: f64 = 0.0;
        var var_sum: f64 = 0.0;
        for (0..batch_size) |b| {
            for (0..channels) |c| {
                var channel_sum: f64 = 0.0;
                for (0..spatial) |s| {
                    const idx = &.{ b, c } ++ std.mem.sliceTo(&.{0}, 0).* ++ &.{s}; // Simplified
                    channel_sum += self.get(idx) orelse 0.0;
                }
                mean += channel_sum / @as(f64, @floatFromInt(spatial));
            }
        }
        mean /= @as(f64, @floatFromInt(batch_size * channels));
        // Variance calculation similar
        const variance = var_sum / @as(f64, @floatFromInt(batch_size * channels)) + eps;
        const std = math.sqrt(variance);
        if (training) {
            // Update running stats
            for (0..channels) |c| {
                const run_mean_idx = &.{c};
                const run_var_idx = &.{c};
                const run_mean_old = running_mean.get(run_mean_idx) orelse 0.0;
                const run_var_old = running_var.get(run_var_idx) orelse 1.0;
                try running_mean.set(run_mean_idx, momentum * run_mean_old + (1.0 - momentum) * mean);
                try running_var.set(run_var_idx, momentum * run_var_old + (1.0 - momentum) * variance);
            }
        } else {
            mean = running_mean.get(&.{0}) orelse 0.0; // Simplified
            const variance = running_var.get(&.{0}) orelse 1.0;
        }
        // Normalize and scale
        for (0..totalElements(self.shape)) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            const normalized = (val - mean) / std;
            const gamma_val = gamma.get(&.{i % channels}) orelse 1.0;
            const beta_val = beta.get(&.{i % channels}) orelse 0.0;
            try result.set(&.{i}, gamma_val * normalized + beta_val);
        }
    }

    // Additional methods for advanced ops: embedding, positional encoding, etc.
    pub fn embedding(self: *Tensor, indices: *const Tensor, vocab_size: usize, embed_dim: usize, allocator: Allocator) !Tensor {
        var result = try Tensor.init(allocator, &.{ indices.shape[0], embed_dim }, .f64);
        for (0..indices.shape[0]) |i| {
            const idx_val = @as(usize, @intFromFloat(indices.get(&.{i}) orelse 0.0));
            if (idx_val < vocab_size) {
                for (0..embed_dim) |d| {
                    const embed_idx = &.{ idx_val * embed_dim + d };
                    const val = self.get(embed_idx) orelse 0.0;
                    try result.set(&.{ i, d }, val);
                }
            }
        }
        return result;
    }

    pub fn positional_encoding(self: *Tensor, max_len: usize, d_model: usize, allocator: Allocator) !Tensor {
        var pe = try Tensor.init(allocator, &.{ max_len, d_model }, .f64);
        const div_term = try allocator.alloc(f64, d_model / 2);
        defer allocator.free(div_term);
        for (0..d_model / 2) |i| {
            div_term[i] = math.pow(f64, 10000.0, -2.0 * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(d_model)));
        }
        for (0..max_len) |pos| {
            for (0..d_model / 2) |i| {
                const angle = @as(f64, @floatFromInt(pos)) * div_term[i];
                try pe.set(&.{ pos, 2 * i }, math.sin(angle));
                try pe.set(&.{ pos, 2 * i + 1 }, math.cos(angle));
            }
        }
        return pe;
    }

    // Sparse operations for efficiency
    pub fn sparse_matmul(self: *const Tensor, other: *const Tensor, sparsity: f64, allocator: Allocator) !Tensor {
        // Implement sparse multiplication with given sparsity
        const dense_result = try self.matmul(other, allocator);
        // Apply sparsity mask
        var mask = try create_random_mask(allocator, dense_result.shape, sparsity);
        var sparse_result = try Tensor.init(allocator, dense_result.shape, .f64);
        try dense_result.mul(&mask, &sparse_result);
        return sparse_result;
    }

    fn create_random_mask(allocator: Allocator, shape: Shape, sparsity: f64) !Tensor {
        const total = totalElements(shape);
        var mask = try Tensor.init(allocator, shape, .f64);
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.rand.addSystemEntropy(&seed);
            break :blk seed;
        });
        const rand = prng.random();
        for (0..total) |i| {
            const keep = if (rand.float(f64) > sparsity) 1.0 else 0.0;
            try mask.set(&.{i}, keep);
        }
        return mask;
    }

    // Quantum-inspired operations
    pub fn hadamard_transform(self: *Tensor, allocator: Allocator) !Tensor {
        // Simulate Hadamard gate on tensor data
        var result = try self.clone(allocator);
        const n_qubits = try math.log2_int_ceil(usize, totalElements(self.shape));
        const size = @as(usize, 1 << @intCast(n_qubits));
        for (0..size) |i| {
            var sum: f64 = 0.0;
            for (0..size) |j| {
                if ((i & j) == 0) {
                    sum += self.get(&.{j}) orelse 0.0;
                } else {
                    sum -= self.get(&.{j}) orelse 0.0;
                }
            }
            try result.set(&.{i}, sum / math.sqrt(@as(f64, @floatFromInt(size))));
        }
        return result;
    }

    // Celestial normalization based on orbital mechanics
    pub fn celestial_norm(self: *Tensor, mu: f64, r: f64, allocator: Allocator) !Tensor {
        var result = try self.clone(allocator);
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            const normalized = val * math.sqrt(mu / r); // Simplified Kepler norm
            try result.set(&.{i}, normalized);
        }
        return result;
    }

    // B-spline basis evaluation for KAN
    pub fn b_spline_basis(self: *const Tensor, knots: []f64, degree: usize, result: *Tensor) !void {
        if (self.shape.len != 1 or result.shape.len != 1 or self.shape[0] != result.shape[0]) {
            return error.ShapeMismatch;
        }
        for (0..self.shape[0]) |i| {
            const x = self.get(&.{i}) orelse 0.0;
            var basis_val: f64 = 0.0;
            // Cox-de Boor recursion for B-spline
            var nknots = try std.ArrayList(f64).init(self.allocator);
            defer nknots.deinit();
            try nknots.appendSlice(knots);
            basis_val = deBoor(x, nknots.items, degree, 0);
            try result.set(&.{i}, basis_val);
        }
    }

    fn deBoor(x: f64, knots: []f64, degree: usize, i: usize) f64 {
        if (degree == 0) {
            if (x >= knots[i] and x < knots[i + 1]) return 1.0;
            return 0.0;
        }
        var left_num = if (x - knots[i] != 0.0) (x - knots[i]) / (knots[i + degree] - knots[i]) else 0.0;
        var right_num = if (knots[i + degree + 1] - x != 0.0) (knots[i + degree + 1] - x) / (knots[i + degree + 1] - knots[i + 1]) else 0.0;
        var left_denom = if (knots[i + degree] - knots[i] != 0.0) 1.0 / (knots[i + degree] - knots[i]) else 0.0;
        var right_denom = if (knots[i + degree + 1] - knots[i + 1] != 0.0) 1.0 / (knots[i + degree + 1] - knots[i + 1]) else 0.0;
        const left = left_num * deBoor(x, knots, degree - 1, i);
        const right = right_num * deBoor(x, knots, degree - 1, i + 1);
        return left + right;
    }

    // Lorenz attractor embedding for tokenizer
    pub fn lorenz_embedding(self: *Tensor, sigma: f64, rho: f64, beta: f64, dt: f64, steps: usize, allocator: Allocator) !Tensor {
        var state = try Tensor.init(allocator, &.{3}, .f64);
        try state.set(&.{0}, 0.1); try state.set(&.{1}, 1.0); try state.set(&.{2}, 1.05); // Initial conditions
        var trajectory = try std.ArrayList(Tensor).init(allocator);
        defer {
            for (trajectory.items) |t| t.deinit();
            trajectory.deinit();
        }
        for (0..steps) |step| {
            var dx = sigma * (state.get(&.{1}).? - state.get(&.{0}).?);
            var dy = state.get(&.{0}).? * (rho - state.get(&.{2}).?) - state.get(&.{1}).?;
            var dz = state.get(&.{0}).? * state.get(&.{1}).? - beta * state.get(&.{2}).?;
            try state.set(&.{0}, state.get(&.{0}).? + dt * dx);
            try state.set(&.{1}, state.get(&.{1}).? + dt * dy);
            try state.set(&.{2}, state.get(&.{2}).? + dt * dz);
            var step_tensor = try state.clone(allocator);
            try trajectory.append(step_tensor);
        }
        // Embed input into trajectory
        var embedded = try Tensor.init(allocator, &.{ self.shape[0], 3 * steps }, .f64);
        for (0..self.shape[0]) |i| {
            const input_val = self.get(&.{i}) orelse 0.0;
            var embed_idx: usize = 0;
            for (0..steps) |s| {
                const traj_val = trajectory.items[s].get(&.{0}).?; // Use x component
                const combined = input_val * traj_val;
                try embedded.set(&.{ i, embed_idx }, combined);
                embed_idx += 1;
                try embedded.set(&.{ i, embed_idx }, trajectory.items[s].get(&.{1}).?);
                embed_idx += 1;
                try embedded.set(&.{ i, embed_idx }, trajectory.items[s].get(&.{2}).?);
                embed_idx += 1;
            }
        }
        return embedded;
    }

    // TGN message passing
    pub fn tgn_update(self: *Tensor, edge_features: *const Tensor, node_features: *const Tensor, time_encoding: *const Tensor, allocator: Allocator) !Tensor {
        // Simplified TGN update: aggregate neighbors
        const num_nodes = self.shape[0];
        const feat_dim = self.shape[1];
        var updated = try Tensor.init(allocator, self.shape, .f64);
        @memcpy(updated.data, self.data);
        for (0..num_nodes) |node| {
            var agg: f64 = 0.0;
            const num_neighbors = @as(f64, @floatFromInt(edge_features.shape[0]));
            for (0..edge_features.shape[0]) |e| {
                agg += edge_features.get(&.{ e, 0 }).?; // Assume edge weight in first dim
            }
            agg /= num_neighbors;
            for (0..feat_dim) |d| {
                const old_feat = self.get(&.{ node, d }).?;
                const time_factor = time_encoding.get(&.{ node }).?;
                const new_feat = old_feat + agg * time_factor;
                try updated.set(&.{ node, d }, new_feat);
            }
        }
        return updated;
    }

    // SSM state update (S4D variant)
    pub fn ssm_s4d_update(self: *Tensor, A: *const Tensor, B: *const Tensor, C: *const Tensor, Delta: *const Tensor, u: *const Tensor, dt: f64, allocator: Allocator) !Tensor {
        const state_dim = self.shape[0];
        const seq_len = u.shape[0];
        var states = try std.ArrayList(Tensor).init(allocator);
        defer {
            for (states.items) |s| s.deinit();
            states.deinit();
        }
        var h = try self.clone(allocator);
        try states.append(h);
        for (0..seq_len) |t| {
            var h_new = try Tensor.init(allocator, &.{state_dim}, .f64);
            @memset(h_new.data, 0);
            for (0..state_dim) |i| {
                const a_i = A.get(&.{i}).?;
                const exp_a = math.exp(a_i * dt);
                const h_i = h.get(&.{i}).?;
                const b_i = B.get(&.{i}).?;
                const delta_i = Delta.get(&.{i}).?;
                const u_t = u.get(&.{t}).?;
                const term1 = exp_a * h_i;
                const term2 = b_i * delta_i * u_t;
                try h_new.set(&.{i}, term1 + term2);
            }
            h = h_new;
            try states.append(h);
        }
        // Output y = C h
        var y = try Tensor.init(allocator, &.{seq_len}, .f64);
        for (0..seq_len) |t| {
            var y_t: f64 = 0.0;
            const h_t = states.items[t];
            for (0..state_dim) |i| {
                y_t += C.get(&.{i}).? * h_t.get(&.{i}).?;
            }
            try y.set(&.{t}, y_t);
        }
        return y;
    }

    // Hyena convolution for long-range dependencies
    pub fn hyena_conv(self: *Tensor, filter: *const Tensor, bias: *const Tensor, seq_len: usize, allocator: Allocator) !Tensor {
        const feat_dim = self.shape[1];
        var result = try Tensor.init(allocator, self.shape, .f64);
        for (0..seq_len) |t| {
            var conv_val: f64 = 0.0;
            for (0..feat_dim) |d| {
                const x_td = self.get(&.{t, d}).?;
                const f_d = filter.get(&.{d}).?;
                conv_val += x_td * f_d;
            }
            const b = bias.get(&.{0}).?;
            try result.set(&.{t, 0}, conv_val + b); // Simplified to 1D output
        }
        return result;
    }

    // Mamba2 selective scan
    pub fn mamba2_scan(self: *Tensor, A_log: *const Tensor, B: *const Tensor, C: *const Tensor, Delta: *const Tensor, allocator: Allocator) !Tensor {
        const d_state = A_log.shape[0];
        const seq_len = self.shape[0];
        var h = try Tensor.init(allocator, &.{d_state}, .f64);
        @memset(h.data, 0);
        var y = try Tensor.init(allocator, &.{seq_len}, .f64);
        for (0..seq_len) |t| {
            const x_t = self.get(&.{t}).?;
            var delta_t = try Tensor.init(allocator, &.{d_state}, .f64);
            for (0..d_state) |s| {
                const delta_s = math.exp(Delta.get(&.{s}).?);
                try delta_t.set(&.{s}, delta_s);
            }
            var A_t = try Tensor.init(allocator, &.{d_state}, .f64);
            for (0..d_state) |s| {
                const a_log_s = A_log.get(&.{s}).?;
                try A_t.set(&.{s}, math.exp(a_log_s));
            }
            var dh = try Tensor.init(allocator, &.{d_state}, .f64);
            for (0..d_state) |s| {
                const b_s = B.get(&.{t, s}).?;
                const h_s = h.get(&.{s}).?;
                const term = (x_t * b_s - h_s) * delta_t.get(&.{s}).?;
                try dh.set(&.{s}, term);
            }
            try h.add(&dh, &h);
            var y_t: f64 = 0.0;
            for (0..d_state) |s| {
                y_t += C.get(&.{t, s}).? * h.get(&.{s}).?;
            }
            try y.set(&.{t}, y_t);
            dh.deinit(); A_t.deinit(); delta_t.deinit();
        }
        return y;
    }

