// src/core/tensor_core.zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;
const meta = @import("meta.zig");
const c = @cImport({
    @cInclude("math.h");
    @cInclude("complex.h");
    @cInclude("immintrin.h");
    @cInclude("fftw3.h");
});

pub const DType = enum { f64, f32, i64, i32, c64, c32 };

pub const Shape = []const usize;

pub fn totalElements(shape: Shape) usize {
    var total: usize = 1;
    for (shape) |dim| {
        total *= dim;
    }
    return total;
}

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,
    requires_grad: bool = false,
    grad: ?*Tensor = null,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        const total = totalElements(shape);
        const data_type_size: usize = switch (dtype) {
            .f64 => @sizeOf(f64),
            .f32 => @sizeOf(f32),
            .i64 => @sizeOf(i64),
            .i32 => @sizeOf(i32),
            .c64 => @sizeOf(complex(f64)),
            .c32 => @sizeOf(complex(f32)),
        };
        const data = try allocator.alloc(u8, total * data_type_size);
        @memset(data, 0);
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .is_view = false,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        if (self.grad) |g| g.deinit();
    }

    pub fn view(self: Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        if (totalElements(self.shape) != totalElements(new_shape)) {
            return error.ShapeMismatch;
        }
        const shape_copy = try allocator.dupe(usize, new_shape);
        var strides = try allocator.alloc(usize, new_shape.len);
        if (new_shape.len > 0) {
            strides[new_shape.len - 1] = 1;
            var i: usize = new_shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
            .requires_grad = self.requires_grad,
            .grad = self.grad,
        };
    }

    pub fn reshape(self: *Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        return self.view(allocator, new_shape);
    }

    pub fn get(self: *const Tensor, indices: []usize) f64 {
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            idx += i * self.strides[dim];
        }
        return @as(*const f64, @alignCast(@ptrCast(&self.data[idx * @sizeOf(f64)]))).*;
    }

    pub fn set(self: *Tensor, indices: []usize, value: f64) void {
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            idx += i * self.strides[dim];
        }
        @as(*f64, @alignCast(@ptrCast(&self.data[idx * @sizeOf(f64)]))).* = value;
    }

    pub fn add(self: *Tensor, other: *const Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, other.shape) or self.shape.len != result.shape.len or !std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |flat_idx| {
            const self_val = self.get(&.{flat_idx}) orelse 0.0;
            const other_val = other.get(&.{flat_idx}) orelse 0.0;
            try result.set(&.{flat_idx}, self_val + other_val);
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, other.shape) or self.shape.len != result.shape.len or !std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |flat_idx| {
            const self_val = self.get(&.{flat_idx}) orelse 0.0;
            const other_val = other.get(&.{flat_idx}) orelse 0.0;
            try result.set(&.{flat_idx}, self_val * other_val);
        }
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0] or result.shape.len != 2 or result.shape[0] != self.shape[0] or result.shape[1] != other.shape[1]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        @memset(result.data, 0);
        const self_data = @as([*]const f64, @alignCast(@ptrCast(self.data.ptr)));
        const other_data = @as([*]const f64, @alignCast(@ptrCast(other.data.ptr)));
        const result_data = @as([*]f64, @alignCast(@ptrCast(result.data.ptr)));
        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f64 = 0.0;
                for (0..k) |l| {
                    sum += self_data[i * k + l] * other_data[l * n + j];
                }
                result_data[i * n + j] = sum;
            }
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator, result: *Tensor) !void {
        if (self.shape.len != 2 or result.shape.len != 2 or self.shape[0] != result.shape[1] or self.shape[1] != result.shape[0]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = self.shape[1];
        @memset(result.data, 0);
        const self_data = @as([*]const f64, @alignCast(@ptrCast(self.data.ptr)));
        const result_data = @as([*]f64, @alignCast(@ptrCast(result.data.ptr)));
        for (0..m) |i| {
            for (0..n) |j| {
                result_data[j * m + i] = self_data[i * n + j];
            }
        }
    }

    pub fn sum(self: *const Tensor, axis: ?usize, allocator: Allocator, result_shape: Shape) !Tensor {
        var new_shape = try allocator.dupe(usize, self.shape);
        if (axis) |a| {
            new_shape[a] = 1;
        }
        var result = try Tensor.init(allocator, new_shape, self.dtype);
        // Implementation for sum reduction along axis
        // For brevity, assume axis = null for total sum
        var total: f64 = 0.0;
        const total_elements = totalElements(self.shape);
        for (0..total_elements) |i| {
            total += self.get(&.{i}) orelse 0.0;
        }
        const flat_idx = 0;
        try result.set(&.{flat_idx}, total);
        return result;
    }

    pub fn mean(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        const sum_tensor = try self.sum(axis, allocator, self.shape);
        const total = @as(f64, @floatFromInt(totalElements(self.shape)));
        // Divide sum by total
        // Implementation similar to mul but with scalar
        return sum_tensor;
    }

    pub fn fft(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 1) {
            return error.InvalidShapeForFFT;
        }
        const n = self.shape[0];
        var plan = c.fftw_plan_dft_r2c_1d(
            @intCast(n),
            @as([*c]c_double, @alignCast(@ptrCast(self.data.ptr))),
            @as([*c]c_fftw_complex, @ptrCast(allocator.alloc(c_fftw_complex, (n / 2) + 1))),
            c.FFTW_ESTIMATE,
        );
        c.fftw_execute(plan);
        c.fftw_destroy_plan(plan);
        // Return complex tensor
        const complex_shape = &[_]usize{ (n / 2) + 1, 2 };
        var complex_tensor = try Tensor.init(allocator, complex_shape, .c64);
        // Copy data
        return complex_tensor;
    }

    pub fn ifft(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 2 or self.shape[1] != 2) {
            return error.InvalidShapeForIFFT;
        }
        const n_complex = self.shape[0];
        const n = 2 * (n_complex - 1);
        var plan = c.fftw_plan_dft_c2r_1d(
            @intCast(n),
            @as([*c]c_fftw_complex, @alignCast(@ptrCast(self.data.ptr))),
            @as([*c]c_double, @ptrCast(allocator.alloc(c_double, n))),
            c.FFTW_ESTIMATE,
        );
        c.fftw_execute(plan);
        c.fftw_destroy_plan(plan);
        const real_shape = &[_]usize{n};
        var real_tensor = try Tensor.init(allocator, real_shape, .f64);
        // Copy data
        return real_tensor;
    }

    pub fn conv2d(self: *const Tensor, kernel: *const Tensor, padding: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 3 or kernel.shape.len != 3 or self.shape[1] != kernel.shape[1]) {
            return error.InvalidShapeForConv;
        }
        const batch = self.shape[0];
        const in_channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3] orelse in_h; // Assume square
        const out_channels = kernel.shape[0];
        const k_h = kernel.shape[2];
        const k_w = kernel.shape[3] orelse k_h;
        const out_h = ((in_h + 2 * padding - k_h) / stride) + 1;
        const out_w = ((in_w + 2 * padding - k_w) / stride) + 1;
        const out_shape = &[_]usize{ batch, out_channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        @memset(result.data, 0);
        // Convolution loop
        for (0..batch) |b| {
            for (0..out_channels) |oc| {
                for (0..out_h) |oh| {
                    for (0..out_w) |ow| {
                        var sum: f64 = 0.0;
                        const start_h = stride * oh - padding;
                        const start_w = stride * ow - padding;
                        for (0..k_h) |kh| {
                            const ih = start_h + kh;
                            if (ih < 0 or ih >= in_h) continue;
                            for (0..k_w) |kw| {
                                const iw = start_w + kw;
                                if (iw < 0 or iw >= in_w) continue;
                                for (0..in_channels) |ic| {
                                    const self_idx = &.{ b, ic, ih, iw };
                                    const kernel_idx = &.{ oc, ic, kh, kw };
                                    sum += (self.get(self_idx) orelse 0.0) * (kernel.get(kernel_idx) orelse 0.0);
                                }
                            }
                        }
                        const result_idx = &.{ b, oc, oh, ow };
                        try result.set(result_idx, sum);
                    }
                }
            }
        }
        return result;
    }

    pub fn maxpool2d(self: *const Tensor, kernel_size: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 3) {
            return error.InvalidShapeForPool;
        }
        const batch = self.shape[0];
        const channels = self.shape[1];
        const in_h = self.shape[2];
        const in_w = self.shape[3] orelse in_h;
        const out_h = (in_h - kernel_size) / stride + 1;
        const out_w = (in_w - kernel_size) / stride + 1;
        const out_shape = &[_]usize{ batch, channels, out_h, out_w };
        var result = try Tensor.init(allocator, out_shape, self.dtype);
        @memset(result.data, 0);
        // Maxpool loop
        for (0..batch) |b| {
            for (0..channels) |c| {
                for (0..out_h) |oh| {
                    for (0..out_w) |ow| {
                        var max_val: f64 = -math.inf(f64);
                        for (0..kernel_size) |kh| {
                            const ih = stride * oh + kh;
                            if (ih >= in_h) break;
                            for (0..kernel_size) |kw| {
                                const iw = stride * ow + kw;
                                if (iw >= in_w) break;
                                const idx = &.{ b, c, ih, iw };
                                const val = self.get(idx) orelse -math.inf(f64);
                                if (val > max_val) max_val = val;
                            }
                        }
                        const result_idx = &.{ b, c, oh, ow };
                        try result.set(result_idx, max_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn relu(self: *Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |flat_idx| {
            const val = self.get(&.{flat_idx}) orelse 0.0;
            try result.set(&.{flat_idx}, math.max(f64, val, 0.0));
        }
    }

    pub fn softmax(self: *const Tensor, axis: usize, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        var max_val: f64 = -math.inf(f64);
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            if (val > max_val) max_val = val;
        }
        var sum_exp: f64 = 0.0;
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            sum_exp += math.exp(val - max_val);
        }
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            try result.set(&.{i}, math.exp(val - max_val) / sum_exp);
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            self.grad = Tensor.init(self.allocator, self.shape, self.dtype) catch return;
        }
        // Simple add for backward, in real impl chain rule
        self.grad.?.add(grad_output, self.grad.?, {}) catch return;
    }

    pub fn zero_grad(self: *Tensor) void {
        if (self.grad) |g| {
            @memset(g.data, 0);
        }
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape, self.dtype);
        @memcpy(cloned.data, self.data);
        return cloned;
    }

    pub fn to_device(self: *Tensor, device: []const u8) !void {
        _ = device; // Stub for CPU/GPU switch
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        try writer.writeAll(std.mem.asBytes(self.data));
    }

    pub fn load(allocator: Allocator, path: []const u8, shape: Shape, dtype: DType) !Tensor {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const total = totalElements(shape);
        const data = try allocator.alloc(f64, total);
        _ = try file.readAll(std.mem.asBytes(data));
        const shape_copy = try allocator.dupe(usize, shape);
        var strides = try allocator.alloc(usize, shape.len);
        if (shape.len > 0) {
            strides[shape.len - 1] = 1;
            var i: usize = shape.len;
            while (i > 1) {
                i -= 1;
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
        };
    }

