    pub fn adam_update(self: *Tensor, m: *Tensor, v: *Tensor, beta1: f64, beta2: f64, lr: f64, t: usize, eps: f64) void {
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const grad_val = if (self.grad) |g| g.get(&.{i}) orelse 0.0 else 0.0;
            const m_old = m.get(&.{i}) orelse 0.0;
            const v_old = v.get(&.{i}) orelse 0.0;
            const m_new = beta1 * m_old + (1.0 - beta1) * grad_val;
            const v_new = beta2 * v_old + (1.0 - beta2) * grad_val * grad_val;
            try m.set(&.{i}, m_new);
            try v.set(&.{i}, v_new);
            const m_hat = m_new / (1.0 - math.pow(f64, beta1, @floatFromInt(t)));
            const v_hat = v_new / (1.0 - math.pow(f64, beta2, @floatFromInt(t)));
            const update = -lr * m_hat / (math.sqrt(v_hat) + eps);
            const old_val = self.get(&.{i}) orelse 0.0;
            try self.set(&.{i}, old_val + update);
        }
    }

    pub fn spectral_norm(self: *Tensor, allocator: Allocator, num_power_iters: usize) !f64 {
        var u = try self.clone(allocator);
        defer u.deinit();
        const total = totalElements(self.shape);
        for (0..num_power_iters) |_|
        {
            var ut = try u.transpose(allocator, self); // Assume square
            defer ut.deinit();
            var v = try Tensor.init(allocator, self.shape, .f64);
            defer v.deinit();
            try self.matmul(&u, &v); // A u
            u = v;
        }
        var u_norm_sq: f64 = 0.0;
        for (0..total) |i| {
            const val = u.get(&.{i}) orelse 0.0;
            u_norm_sq += val * val;
        }
        return math.sqrt(u_norm_sq);
    }

    pub fn dropout(self: *Tensor, p: f64, rng: *DefaultPrng, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var seed = rng.random().int(usize);
        var prng = DefaultPrng.init(seed);
        const rand = prng.random();
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            if (rand.float(f64) < p) {
                try result.set(&.{i}, 0.0);
            } else {
                try result.set(&.{i}, val / (1.0 - p));
            }
        }
    }

    pub fn layer_norm(self: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape) or !std.mem.eql(usize, self.shape, gamma.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var mean: f64 = 0.0;
        var var_sum: f64 = 0.0;
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            mean += val;
        }
        mean /= @as(f64, @floatFromInt(total));
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            var_sum += (val - mean) * (val - mean);
        }
        const variance = var_sum / @as(f64, @floatFromInt(total)) + eps;
        const std = math.sqrt(variance);
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            const normalized = (val - mean) / std;
            const gamma_val = gamma.get(&.{i}) orelse 1.0;
            const beta_val = beta.get(&.{i}) orelse 0.0;
            try result.set(&.{i}, gamma_val * normalized + beta_val);
        }
    }

    pub fn gelu(self: *Tensor, result: *Tensor) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const x = self.get(&.{i}) orelse 0.0;
            const gelu_approx = x * (1.0 / (1.0 + math.exp(-1.6732632423543772848170429916717 * x * x)));
            try result.set(&.{i}, gelu_approx);
        }
    }

    pub fn batch_norm(self: *Tensor, running_mean: *Tensor, running_var: *Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, training: bool, momentum: f64, result: *Tensor, allocator: Allocator) !void {
        if (!std.mem.eql(usize, self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const batch_size = self.shape[0];
        const channels = self.shape[1];
        const spatial = totalElements(self.shape) / (batch_size * channels);
        var mean: f64 = 0.0;
        var var_sum: f64 = 0.0;
        for (0..batch_size) |b| {
            for (0..channels) |c| {
                var channel_sum: f64 = 0.0;
                for (0..spatial) |s| {
                    const idx = &.{ b, c } ++ std.mem.sliceTo(&.{0}, 0).* ++ &.{s}; // Simplified
                    channel_sum += self.get(idx) orelse 0.0;
                }
                mean += channel_sum / @as(f64, @floatFromInt(spatial));
            }
        }
        mean /= @as(f64, @floatFromInt(batch_size * channels));
        // Variance calculation similar
        const variance = var_sum / @as(f64, @floatFromInt(batch_size * channels)) + eps;
        const std = math.sqrt(variance);
        if (training) {
            // Update running stats
            for (0..channels) |c| {
                const run_mean_idx = &.{c};
                const run_var_idx = &.{c};
                const run_mean_old = running_mean.get(run_mean_idx) orelse 0.0;
                const run_var_old = running_var.get(run_var_idx) orelse 1.0;
                try running_mean.set(run_mean_idx, momentum * run_mean_old + (1.0 - momentum) * mean);
                try running_var.set(run_var_idx, momentum * run_var_old + (1.0 - momentum) * variance);
            }
        } else {
            mean = running_mean.get(&.{0}) orelse 0.0; // Simplified
            const variance = running_var.get(&.{0}) orelse 1.0;
        }
        // Normalize and scale
        for (0..totalElements(self.shape)) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            const normalized = (val - mean) / std;
            const gamma_val = gamma.get(&.{i % channels}) orelse 1.0;
            const beta_val = beta.get(&.{i % channels}) orelse 0.0;
            try result.set(&.{i}, gamma_val * normalized + beta_val);
        }
    }

    // Additional methods for advanced ops: embedding, positional encoding, etc.
    pub fn embedding(self: *Tensor, indices: *const Tensor, vocab_size: usize, embed_dim: usize, allocator: Allocator) !Tensor {
        var result = try Tensor.init(allocator, &.{ indices.shape[0], embed_dim }, .f64);
        for (0..indices.shape[0]) |i| {
            const idx_val = @as(usize, @intFromFloat(indices.get(&.{i}) orelse 0.0));
            if (idx_val < vocab_size) {
                for (0..embed_dim) |d| {
                    const embed_idx = &.{ idx_val * embed_dim + d };
                    const val = self.get(embed_idx) orelse 0.0;
                    try result.set(&.{ i, d }, val);
                }
            }
        }
        return result;
    }

    pub fn positional_encoding(self: *Tensor, max_len: usize, d_model: usize, allocator: Allocator) !Tensor {
        var pe = try Tensor.init(allocator, &.{ max_len, d_model }, .f64);
        const div_term = try allocator.alloc(f64, d_model / 2);
        defer allocator.free(div_term);
        for (0..d_model / 2) |i| {
            div_term[i] = math.pow(f64, 10000.0, -2.0 * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(d_model)));
        }
        for (0..max_len) |pos| {
            for (0..d_model / 2) |i| {
                const angle = @as(f64, @floatFromInt(pos)) * div_term[i];
                try pe.set(&.{ pos, 2 * i }, math.sin(angle));
                try pe.set(&.{ pos, 2 * i + 1 }, math.cos(angle));
            }
        }
        return pe;
    }

    // Sparse operations for efficiency
    pub fn sparse_matmul(self: *const Tensor, other: *const Tensor, sparsity: f64, allocator: Allocator) !Tensor {
        // Implement sparse multiplication with given sparsity
        const dense_result = try self.matmul(other, allocator);
        // Apply sparsity mask
        var mask = try create_random_mask(allocator, dense_result.shape, sparsity);
        var sparse_result = try Tensor.init(allocator, dense_result.shape, .f64);
        try dense_result.mul(&mask, &sparse_result);
        return sparse_result;
    }

    fn create_random_mask(allocator: Allocator, shape: Shape, sparsity: f64) !Tensor {
        const total = totalElements(shape);
        var mask = try Tensor.init(allocator, shape, .f64);
        var prng = std.rand.DefaultPrng.init(blk: {
            var seed: u64 = undefined;
            std.rand.addSystemEntropy(&seed);
            break :blk seed;
        });
        const rand = prng.random();
        for (0..total) |i| {
            const keep = if (rand.float(f64) > sparsity) 1.0 else 0.0;
            try mask.set(&.{i}, keep);
        }
        return mask;
    }

    // Quantum-inspired operations
    pub fn hadamard_transform(self: *Tensor, allocator: Allocator) !Tensor {
        // Simulate Hadamard gate on tensor data
        var result = try self.clone(allocator);
        const n_qubits = try math.log2_int_ceil(usize, totalElements(self.shape));
        const size = @as(usize, 1 << @intCast(n_qubits));
        for (0..size) |i| {
            var sum: f64 = 0.0;
            for (0..size) |j| {
                if ((i & j) == 0) {
                    sum += self.get(&.{j}) orelse 0.0;
                } else {
                    sum -= self.get(&.{j}) orelse 0.0;
                }
            }
            try result.set(&.{i}, sum / math.sqrt(@as(f64, @floatFromInt(size))));
        }
        return result;
    }

    // Celestial normalization based on orbital mechanics
    pub fn celestial_norm(self: *Tensor, mu: f64, r: f64, allocator: Allocator) !Tensor {
        var result = try self.clone(allocator);
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const val = self.get(&.{i}) orelse 0.0;
            const normalized = val * math.sqrt(mu / r); // Simplified Kepler norm
            try result.set(&.{i}, normalized);
        }
        return result;
    }

    // B-spline basis evaluation for KAN
    pub fn b_spline_basis(self: *const Tensor, knots: []f64, degree: usize, result: *Tensor) !void {
        if (self.shape.len != 1 or result.shape.len != 1 or self.shape[0] != result.shape[0]) {
            return error.ShapeMismatch;
        }
        for (0..self.shape[0]) |i| {
            const x = self.get(&.{i}) orelse 0.0;
            var basis_val: f64 = 0.0;
            // Cox-de Boor recursion for B-spline
            var nknots = try std.ArrayList(f64).init(self.allocator);
            defer nknots.deinit();
            try nknots.appendSlice(knots);
            basis_val = deBoor(x, nknots.items, degree, 0);
            try result.set(&.{i}, basis_val);
        }
    }

    fn deBoor(x: f64, knots: []f64, degree: usize, i: usize) f64 {
        if (degree == 0) {
            if (x >= knots[i] and x < knots[i + 1]) return 1.0;
            return 0.0;
        }
        var left_num = if (x - knots[i] != 0.0) (x - knots[i]) / (knots[i + degree] - knots[i]) else 0.0;
        var right_num = if (knots[i + degree + 1] - x != 0.0) (knots[i + degree + 1] - x) / (knots[i + degree + 1] - knots[i + 1]) else 0.0;
        var left_denom = if (knots[i + degree] - knots[i] != 0.0) 1.0 / (knots[i + degree] - knots[i]) else 0.0;
        var right_denom = if (knots[i + degree + 1] - knots[i + 1] != 0.0) 1.0 / (knots[i + degree + 1] - knots[i + 1]) else 0.0;
        const left = left_num * deBoor(x, knots, degree - 1, i);
        const right = right_num * deBoor(x, knots, degree - 1, i + 1);
        return left + right;
    }

    // Lorenz attractor embedding for tokenizer
    pub fn lorenz_embedding(self: *Tensor, sigma: f64, rho: f64, beta: f64, dt: f64, steps: usize, allocator: Allocator) !Tensor {
        var state = try Tensor.init(allocator, &.{3}, .f64);
        try state.set(&.{0}, 0.1); try state.set(&.{1}, 1.0); try state.set(&.{2}, 1.05); // Initial conditions
        var trajectory = try std.ArrayList(Tensor).init(allocator);
        defer {
            for (trajectory.items) |t| t.deinit();
            trajectory.deinit();
        }
        for (0..steps) |step| {
            var dx = sigma * (state.get(&.{1}).? - state.get(&.{0}).?);
            var dy = state.get(&.{0}).? * (rho - state.get(&.{2}).?) - state.get(&.{1}).?;
            var dz = state.get(&.{0}).? * state.get(&.{1}).? - beta * state.get(&.{2}).?;
            try state.set(&.{0}, state.get(&.{0}).? + dt * dx);
            try state.set(&.{1}, state.get(&.{1}).? + dt * dy);
            try state.set(&.{2}, state.get(&.{2}).? + dt * dz);
            var step_tensor = try state.clone(allocator);
            try trajectory.append(step_tensor);
        }
        // Embed input into trajectory
        var embedded = try Tensor.init(allocator, &.{ self.shape[0], 3 * steps }, .f64);
        for (0..self.shape[0]) |i| {
            const input_val = self.get(&.{i}) orelse 0.0;
            var embed_idx: usize = 0;
            for (0..steps) |s| {
                const traj_val = trajectory.items[s].get(&.{0}).?; // Use x component
                const combined = input_val * traj_val;
                try embedded.set(&.{ i, embed_idx }, combined);
                embed_idx += 1;
                try embedded.set(&.{ i, embed_idx }, trajectory.items[s].get(&.{1}).?);
                embed_idx += 1;
                try embedded.set(&.{ i, embed_idx }, trajectory.items[s].get(&.{2}).?);
                embed_idx += 1;
            }
        }
        return embedded;
    }

    // TGN message passing
    pub fn tgn_update(self: *Tensor, edge_features: *const Tensor, node_features: *const Tensor, time_encoding: *const Tensor, allocator: Allocator) !Tensor {
        // Simplified TGN update: aggregate neighbors
        const num_nodes = self.shape[0];
        const feat_dim = self.shape[1];
        var updated = try Tensor.init(allocator, self.shape, .f64);
        @memcpy(updated.data, self.data);
        for (0..num_nodes) |node| {
            var agg: f64 = 0.0;
            const num_neighbors = @as(f64, @floatFromInt(edge_features.shape[0]));
            for (0..edge_features.shape[0]) |e| {
                agg += edge_features.get(&.{ e, 0 }).?; // Assume edge weight in first dim
            }
            agg /= num_neighbors;
            for (0..feat_dim) |d| {
                const old_feat = self.get(&.{ node, d }).?;
                const time_factor = time_encoding.get(&.{ node }).?;
                const new_feat = old_feat + agg * time_factor;
                try updated.set(&.{ node, d }, new_feat);
            }
        }
        return updated;
    }

    // SSM state update (S4D variant)
    pub fn ssm_s4d_update(self: *Tensor, A: *const Tensor, B: *const Tensor, C: *const Tensor, Delta: *const Tensor, u: *const Tensor, dt: f64, allocator: Allocator) !Tensor {
        const state_dim = self.shape[0];
        const seq_len = u.shape[0];
        var states = try std.ArrayList(Tensor).init(allocator);
        defer {
            for (states.items) |s| s.deinit();
