        }
        var h = try self.clone(allocator);
        try states.append(h);
        for (0..seq_len) |t| {
            var h_new = try Tensor.init(allocator, &.{state_dim}, .f64);
            @memset(h_new.data, 0);
            for (0..state_dim) |i| {
                const a_i = A.get(&.{i}).?;
                const exp_a = math.exp(a_i * dt);
                const h_i = h.get(&.{i}).?;
                const b_i = B.get(&.{i}).?;
                const delta_i = Delta.get(&.{i}).?;
                const u_t = u.get(&.{t}).?;
                const term1 = exp_a * h_i;
                const term2 = b_i * delta_i * u_t;
                try h_new.set(&.{i}, term1 + term2);
            }
            h = h_new;
            try states.append(h);
        }
        // Output y = C h
        var y = try Tensor.init(allocator, &.{seq_len}, .f64);
        for (0..seq_len) |t| {
            var y_t: f64 = 0.0;
            const h_t = states.items[t];
            for (0..state_dim) |i| {
                y_t += C.get(&.{i}).? * h_t.get(&.{i}).?;
            }
            try y.set(&.{t}, y_t);
        }
        return y;
    }

    // Hyena convolution for long-range dependencies
    pub fn hyena_conv(self: *Tensor, filter: *const Tensor, bias: *const Tensor, seq_len: usize, allocator: Allocator) !Tensor {
        const feat_dim = self.shape[1];
        var result = try Tensor.init(allocator, self.shape, .f64);
        for (0..seq_len) |t| {
            var conv_val: f64 = 0.0;
            for (0..feat_dim) |d| {
                const x_td = self.get(&.{t, d}).?;
                const f_d = filter.get(&.{d}).?;
                conv_val += x_td * f_d;
            }
            const b = bias.get(&.{0}).?;
            try result.set(&.{t, 0}, conv_val + b); // Simplified to 1D output
        }
        return result;
    }

    // Mamba2 selective scan
    pub fn mamba2_scan(self: *Tensor, A_log: *const Tensor, B: *const Tensor, C: *const Tensor, Delta: *const Tensor, allocator: Allocator) !Tensor {
