// src/core/tensor_core.zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;

pub const DType = enum { f64 };

pub const Shape = []const usize;

pub fn totalElements(shape: Shape) usize {
    var total: usize = 1;
    for (shape) |dim| {
        total *= dim;
    }
    return total;
}

fn computeStridesAlloc(allocator: Allocator, shape: Shape) ![]usize {
    var strides = try allocator.alloc(usize, shape.len);
    if (shape.len > 0) {
        strides[shape.len - 1] = 1;
        var i: isize = @intCast(shape.len) - 2;
        while (i >= 0) : (i -= 1) {
            const ui: usize = @intCast(i);
            strides[ui] = strides[ui + 1] * shape[ui + 1];
        }
    }
    return strides;
}

fn shapesEqual(a: []const usize, b: []const usize) bool {
    if (a.len != b.len) return false;
    return mem.eql(usize, a, b);
}

fn indexOffset(shape: []const usize, strides: []const usize, offset: usize, indices: []const usize) usize {
    var idx: usize = offset;
    var d: usize = 0;
    while (d < shape.len) : (d += 1) {
        idx += indices[d] * strides[d];
    }
    return idx;
}

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: []usize,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,
    requires_grad: bool = false,
    grad: ?Tensor = null,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !Tensor {
        if (dtype != .f64) return error.UnsupportedDType;
        const total = totalElements(shape);
        var data = try allocator.alloc(f64, total);
        std.mem.set(f64, data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        const strides = try computeStridesAlloc(allocator, shape);
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .offset = 0,
            .is_view = false,
            .requires_grad = false,
            .grad = null,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (self.grad) |*g| {
            g.deinit();
            self.grad = null;
        }
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        self.* = undefined;
    }

    pub fn view(self: Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        if (totalElements(self.shape) != totalElements(new_shape)) {
            return error.ShapeMismatch;
        }
        const shape_copy = try allocator.dupe(usize, new_shape);
        const strides = try computeStridesAlloc(allocator, new_shape);
        return Tensor{
            .allocator = self.allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
            .requires_grad = self.requires_grad,
            .grad = null,
        };
    }

    pub fn reshape(self: *Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        return self.view(allocator, new_shape);
    }

    pub fn get(self: *const Tensor, indices: []const usize) f64 {
        std.debug.assert(indices.len == self.shape.len);
        const idx = indexOffset(self.shape, self.strides, self.offset, indices);
        return self.data[idx];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f64) void {
        std.debug.assert(indices.len == self.shape.len);
        const idx = indexOffset(self.shape, self.strides, self.offset, indices);
        self.data[idx] = value;
    }

    pub fn add(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (!shapesEqual(self.shape, other.shape) or !shapesEqual(self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            result.data[i] = self.data[i] + other.data[i];
        }
    }

    pub fn mul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (!shapesEqual(self.shape, other.shape) or !shapesEqual(self.shape, result.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            result.data[i] = self.data[i] * other.data[i];
        }
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or other.shape.len != 2) return error.ShapeMismatch;
        const m = self.shape;
        const k = self.shape;[1]
        if (other.shape != k) return error.ShapeMismatch;
        const n = other.shape;[1]
        if (result.shape.len != 2 or result.shape != m or result.shape != n) return error.ShapeMismatch;[1]

        std.mem.set(f64, result.data, 0.0);
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f64 = 0.0;
                var l: usize = 0;
                while (l < k) : (l += 1) {
                    const a = self.data[i * k + l];
                    const b = other.data[l * n + j];
                    sum += a * b;
                }
                result.data[i * n + j] = sum;
            }
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 2) return error.ShapeMismatch;
        const m = self.shape;
        const n = self.shape;[1]
        var result = try Tensor.init(allocator, &[_]usize{ n, m }, self.dtype);
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                result.data[j * m + i] = self.data[i * n + j];
            }
        }
        return result;
    }

    pub fn sum(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        if (axis == null) {
            var result = try Tensor.init(allocator, &[_]usize{1}, self.dtype);
            var total: f64 = 0.0;
            var i: usize = 0;
            const len = totalElements(self.shape);
            while (i < len) : (i += 1) total += self.data[i];
            result.data = total;
            return result;
        } else {
            const a = axis.?;
            if (a >= self.shape.len) return error.InvalidAxis;
            // Reduce along axis a -> set that dim to 1
            var new_shape = try allocator.dupe(usize, self.shape);
            new_shape[a] = 1;
            var result = try Tensor.init(allocator, new_shape, self.dtype);
            defer allocator.free(new_shape);
            std.mem.set(f64, result.data, 0.0);

            // Iterate all indices and accumulate into reduced index
            const dims = self.shape.len;
            var idx = try allocator.alloc(usize, dims);
            defer allocator.free(idx);
            std.mem.set(usize, idx, 0);

            var done = false;
            while (!done) {
                var ridx = try allocator.alloc(usize, dims);
                defer allocator.free(ridx);
                std.mem.copy(usize, ridx, idx);
                ridx[a] = 0;

                const src_off = indexOffset(self.shape, self.strides, self.offset, idx);
                const dst_off = indexOffset(result.shape, result.strides, result.offset, ridx);
                result.data[dst_off] += self.data[src_off];

                // increment idx
                var d: isize = @intCast(dims) - 1;
                while (d >= 0) : (d -= 1) {
                    const ud: usize = @intCast(d);
                    idx[ud] += 1;
                    if (idx[ud] < self.shape[ud]) break;
                    idx[ud] = 0;
                    if (ud == 0) {
                        done = true;
                    }
                }
            }
            return result;
        }
    }

    pub fn mean(self: *const Tensor, axis: ?usize, allocator: Allocator) !Tensor {
        var s = try self.sum(axis, allocator);
        defer if (axis != null) s.deinit();
        if (axis == null) {
            const total = @as(f64, @floatFromInt(totalElements(self.shape)));
            s.data = s.data / total;
            return s;
        }
        // For reduced tensor, divide by size of reduced axis
        const a = axis.?;
        const denom = @as(f64, @floatFromInt(self.shape[a]));
        var i: usize = 0;
        while (i < s.data.len) : (i += 1) {
            s.data[i] = s.data[i] / denom;
        }
        return s;
    }

    pub fn conv2d(self: *const Tensor, kernel: *const Tensor, padding: usize, stride: usize, allocator: Allocator) !Tensor {
        // NCHW x OIHW
        if (self.shape.len != 4 or kernel.shape.len != 4) return error.InvalidShapeForConv;
        const batch = self.shape;
        const in_channels = self.shape;[1]
        if (kernel.shape != in_channels) return error.InvalidShapeForConv;[1]
        const in_h = self.shape;[2]
        const in_w = self.shape;[3]
        const out_channels = kernel.shape;
        const k_h = kernel.shape;[2]
        const k_w = kernel.shape;[3]
        if (k_h == 0 or k_w == 0) return error.InvalidShapeForConv;
        if (stride == 0) return error.InvalidStride;

        const out_h = if (in_h + 2 * padding >= k_h) ((in_h + 2 * padding - k_h) / stride) + 1 else 0;
        const out_w = if (in_w + 2 * padding >= k_w) ((in_w + 2 * padding - k_w) / stride) + 1 else 0;

        var result = try Tensor.init(allocator, &[_]usize{ batch, out_channels, out_h, out_w }, self.dtype);
        std.mem.set(f64, result.data, 0.0);

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oc: usize = 0;
            while (oc < out_channels) : (oc += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var sum: f64 = 0.0;
                        const start_h: isize = @as(isize, @intCast(oh * stride)) - @as(isize, @intCast(padding));
                        const start_w: isize = @as(isize, @intCast(ow * stride)) - @as(isize, @intCast(padding));
                        var ic: usize = 0;
                        while (ic < in_channels) : (ic += 1) {
                            var kh: usize = 0;
                            while (kh < k_h) : (kh += 1) {
                                const ih_i = start_h + @as(isize, @intCast(kh));
                                if (ih_i < 0 or ih_i >= @as(isize, @intCast(in_h))) continue;
                                var kw: usize = 0;
                                while (kw < k_w) : (kw += 1) {
                                    const iw_i = start_w + @as(isize, @intCast(kw));
                                    if (iw_i < 0 or iw_i >= @as(isize, @intCast(in_w))) continue;
                                    const ih: usize = @intCast(ih_i);
                                    const iw: usize = @intCast(iw_i);
                                    const x = self.get(&.{ b, ic, ih, iw });
                                    const w = kernel.get(&.{ oc, ic, kh, kw });
                                    sum += x * w;
                                }
                            }
                        }
                        result.set(&.{ b, oc, oh, ow }, sum);
                    }
                }
            }
        }

        return result;
    }

    pub fn maxpool2d(self: *const Tensor, kernel_size: usize, stride: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 4) return error.InvalidShapeForPool;
        if (kernel_size == 0 or stride == 0) return error.InvalidShapeForPool;
        const batch = self.shape;
        const channels = self.shape;[1]
        const in_h = self.shape;[2]
        const in_w = self.shape;[3]
        const out_h = if (in_h >= kernel_size) ((in_h - kernel_size) / stride) + 1 else 0;
        const out_w = if (in_w >= kernel_size) ((in_w - kernel_size) / stride) + 1 else 0;

        var result = try Tensor.init(allocator, &[_]usize{ batch, channels, out_h, out_w }, self.dtype);
        std.mem.set(f64, result.data, 0.0);

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var c: usize = 0;
            while (c < channels) : (c += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var max_val: f64 = -math.inf(f64);
                        var kh: usize = 0;
                        while (kh < kernel_size) : (kh += 1) {
                            const ih = oh * stride + kh;
                            if (ih >= in_h) break;
                            var kw: usize = 0;
                            while (kw < kernel_size) : (kw += 1) {
                                const iw = ow * stride + kw;
                                if (iw >= in_w) break;
                                const val = self.get(&.{ b, c, ih, iw });
                                if (val > max_val) max_val = val;
                            }
                        }
                        result.set(&.{ b, c, oh, ow }, max_val);
                    }
                }
            }
        }
        return result;
    }

    pub fn relu(self: *const Tensor, result: *Tensor) !void {
        if (!shapesEqual(self.shape, result.shape)) return error.ShapeMismatch;
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const v = self.data[i];
            result.data[i] = if (v > 0.0) v else 0.0;
        }
    }

    pub fn softmax(self: *const Tensor, axis: usize, result: *Tensor) !void {
        if (!shapesEqual(self.shape, result.shape)) return error.ShapeMismatch;
        if (self.shape.len == 1) {
            // vector softmax
            var max_val: f64 = -math.inf(f64);
            var i: usize = 0;
            while (i < self.data.len) : (i += 1) {
                const v = self.data[i];
                if (v > max_val) max_val = v;
            }
            var sum_exp: f64 = 0.0;
            i = 0;
            while (i < self.data.len) : (i += 1) {
                sum_exp += math.exp(self.data[i] - max_val);
            }
            i = 0;
            while (i < self.data.len) : (i += 1) {
                result.data[i] = math.exp(self.data[i] - max_val) / sum_exp;
            }
            return;
        }
        // Minimal axis-wise softmax over last dim for 2D
        if (self.shape.len != 2) return error.InvalidShapeForSoftmax;
        const rows = self.shape;
        const cols = self.shape;[1]
        if (axis != 1) return error.UnsupportedAxis;
        var r: usize = 0;
        while (r < rows) : (r += 1) {
            var max_val: f64 = -math.inf(f64);
            var c: usize = 0;
            while (c < cols) : (c += 1) {
                const v = self.data[r * cols + c];
                if (v > max_val) max_val = v;
            }
            var sum_exp: f64 = 0.0;
            c = 0;
            while (c < cols) : (c += 1) {
                sum_exp += math.exp(self.data[r * cols + c] - max_val);
            }
            c = 0;
            while (c < cols) : (c += 1) {
                result.data[r * cols + c] = math.exp(self.data[r * cols + c] - max_val) / sum_exp;
            }
        }
    }

    pub fn ensure_grad(self: *Tensor) !void {
        if (self.grad == null) {
            var g = try Tensor.init(self.allocator, self.shape, self.dtype);
            self.grad = g;
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) !void {
        if (!self.requires_grad) return;
        if (!shapesEqual(self.shape, grad_output.shape)) return error.ShapeMismatch;
        try self.ensure_grad();
        var g = self.grad.?;
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            g.data[i] += grad_output.data[i];
        }
        self.grad = g;
    }

    pub fn zero_grad(self: *Tensor) void {
        if (self.grad) |*g| {
            std.mem.set(f64, g.data, 0.0);
        }
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape, self.dtype);
        std.mem.copy(f64, cloned.data, self.data);
        return cloned;
    }

    pub fn to_device(self: *Tensor, device: []const u8) !void {
        _ = self;
        _ = device;
    }

    pub fn save(self: *const Tensor, path: []const u8) !void {
        var file = try std.fs.cwd().createFile(path, .{ .truncate = true });
        defer file.close();
        try file.writer().writeAll(std.mem.asBytes(self.data));
    }

    pub fn load(allocator: Allocator, path: []const u8, shape: Shape, dtype: DType) !Tensor {
        if (dtype != .f64) return error.UnsupportedDType;
        var file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const total = totalElements(shape);
        var data = try allocator.alloc(f64, total);
        const bytes = std.mem.asBytes(data);
        const n = try file.readAll(bytes);
        if (n != bytes.len) return error.UnexpectedEof;
        const shape_copy = try allocator.dupe(usize, shape);
        const strides = try computeStridesAlloc(allocator, shape);
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .dtype = dtype,
            .offset = 0,
            .is_view = false,
            .requires_grad = false,
            .grad = null,
        };
    }

    pub fn adam_update(self: *Tensor, m: *Tensor, v: *Tensor, beta1: f64, beta2: f64, lr: f64, t: usize, eps: f64) !void {
        if (m.data.len != self.data.len or v.data.len != self.data.len) return error.ShapeMismatch;
        const total = totalElements(self.shape);
        const ft = @as(f64, @floatFromInt(t));
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const grad_val = blk: {
                if (self.grad) |g| break :blk g.data[i];
                break :blk 0.0;
            };
            const m_old = m.data[i];
            const v_old = v.data[i];
            const m_new = beta1 * m_old + (1.0 - beta1) * grad_val;
            const v_new = beta2 * v_old + (1.0 - beta2) * grad_val * grad_val;
            m.data[i] = m_new;
            v.data[i] = v_new;
            const m_hat = m_new / (1.0 - math.pow(f64, beta1, ft));
            const v_hat = v_new / (1.0 - math.pow(f64, beta2, ft));
            const update = -lr * m_hat / (math.sqrt(v_hat) + eps);
            self.data[i] += update;
        }
    }

    pub fn dropout(self: *const Tensor, p: f64, rng: *std.rand.DefaultPrng, result: *Tensor) !void {
        if (!shapesEqual(self.shape, result.shape)) return error.ShapeMismatch;
        if (p < 0.0 or p >= 1.0) return error.InvalidDropoutProb;
        const total = totalElements(self.shape);
        var rnd = rng.random();
        var i: usize = 0;
        const scale = 1.0 / (1.0 - p);
        while (i < total) : (i += 1) {
            if (rnd.float(f64) < p) {
                result.data[i] = 0.0;
            } else {
                result.data[i] = self.data[i] * scale;
            }
        }
    }

    pub fn layer_norm(self: *const Tensor, gamma: *const Tensor, beta: *const Tensor, eps: f64, result: *Tensor) !void {
        if (!shapesEqual(self.shape, result.shape) or !shapesEqual(self.shape, gamma.shape) or !shapesEqual(self.shape, beta.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        var mean: f64 = 0.0;
        var i: usize = 0;
        while (i < total) : (i += 1) mean += self.data[i];
        mean /= @as(f64, @floatFromInt(total));

        var var_sum: f64 = 0.0;
        i = 0;
        while (i < total) : (i += 1) {
            const d = self.data[i] - mean;
            var_sum += d * d;
        }
        const variance = var_sum / @as(f64, @floatFromInt(total)) + eps;
        const stdev = math.sqrt(variance);

        i = 0;
        while (i < total) : (i += 1) {
            const normalized = (self.data[i] - mean) / stdev;
            result.data[i] = (gamma.data[i] * normalized) + beta.data[i];
        }
    }

    pub fn gelu(self: *const Tensor, result: *Tensor) !void {
        if (!shapesEqual(self.shape, result.shape)) return error.ShapeMismatch;
        const total = totalElements(self.shape);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            const x = self.data[i];
            // Approximation
            const y = 0.5 * x * (1.0 + math.tanh((math.sqrt(2.0 / math.pi) * (x + 0.044715 * math.pow(f64, x, 3.0)))));
            result.data[i] = y;
        }
    }

    pub fn embedding(self: *const Tensor, indices: *const Tensor, vocab_size: usize, embed_dim: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 2 or self.shape != vocab_size or self.shape != embed_dim) return error.ShapeMismatch;[1]
        if (indices.shape.len != 1) return error.ShapeMismatch;
        var result = try Tensor.init(allocator, &[_]usize{ indices.shape, embed_dim }, .f64);
        var i: usize = 0;
        while (i < indices.shape) : (i += 1) {
            const idx_val_f = indices.data[i];
            const idx_val: usize = @intFromFloat(idx_val_f);
            if (idx_val < vocab_size) {
                var d: usize = 0;
                while (d < embed_dim) : (d += 1) {
                    result.data[i * embed_dim + d] = self.data[idx_val * embed_dim + d];
                }
            } else {
                var d2: usize = 0;
                while (d2 < embed_dim) : (d2 += 1) result.data[i * embed_dim + d2] = 0.0;
            }
        }
        return result;
    }

    pub fn positional_encoding(self: *const Tensor, max_len: usize, d_model: usize, allocator: Allocator) !Tensor {
        _ = self;
        if (d_model == 0 or max_len == 0) return error.InvalidShape;
        var pe = try Tensor.init(allocator, &[_]usize{ max_len, d_model }, .f64);
        var pos: usize = 0;
        while (pos < max_len) : (pos += 1) {
            var i: usize = 0;
            while (i < d_model / 2) : (i += 1) {
                const denom = math.pow(f64, 10000.0, -2.0 * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(d_model)));
                const angle = @as(f64, @floatFromInt(pos)) * denom;
                pe.set(&.{ pos, 2 * i }, math.sin(angle));
                if (2 * i + 1 < d_model) {
                    pe.set(&.{ pos, 2 * i + 1 }, math.cos(angle));
                }
            }
        }
        return pe;
    }

    pub fn sparse_matmul(self: *const Tensor, other: *const Tensor, sparsity: f64, allocator: Allocator) !Tensor {
        if (self.shape.len != 2 or other.shape.len != 2) return error.ShapeMismatch;
        const m = self.shape;
        const k = self.shape;[1]
        if (other.shape != k) return error.ShapeMismatch;
        const n = other.shape;[1]

        var dense = try Tensor.init(allocator, &[_]usize{ m, n }, .f64);
        defer dense.deinit();
        try self.matmul(other, &dense);

        var mask = try Tensor.init(allocator, &[_]usize{ m, n }, .f64);
        defer mask.deinit();
        // Simple mask generator
        var prng = std.rand.DefaultPrng.init(@intCast(@as(u64, @bitCast(std.time.nanoTimestamp()))));
        var rnd = prng.random();
        var i: usize = 0;
        const total = m * n;
        while (i < total) : (i += 1) {
            mask.data[i] = if (rnd.float(f64) > sparsity) 1.0 else 0.0;
        }

        var result = try Tensor.init(allocator, &[_]usize{ m, n }, .f64);
        i = 0;
        while (i < total) : (i += 1) {
            result.data[i] = dense.data[i] * mask.data[i];
        }
        return result;
    }

    pub fn hadamard_transform(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 1) return error.InvalidShapeForHadamard;
        const n = self.shape;
        if (!std.math.isPowerOfTwo(n)) return error.InvalidShapeForHadamard;
        var result = try Tensor.init(allocator, self.shape, .f64);
        const size = n;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            var sum: f64 = 0.0;
            var j: usize = 0;
            while (j < size) : (j += 1) {
                // (-1)^{popcount(i & j) mod 2}
                const bits = @popCount(i & j);
                const sgn: f64 = if ((bits & 1) == 0) 1.0 else -1.0;
                sum += sgn * self.data[j];
            }
            result.data[i] = sum / math.sqrt(@as(f64, @floatFromInt(size)));
        }
        return result;
    }

    pub fn celestial_norm(self: *const Tensor, mu: f64, r: f64, allocator: Allocator) !Tensor {
        var result = try Tensor.init(allocator, self.shape, .f64);
        const total = totalElements(self.shape);
        const factor = math.sqrt(mu / r);
        var i: usize = 0;
        while (i < total) : (i += 1) {
            result.data[i] = self.data[i] * factor;
        }
        return result;
    }

    pub fn b_spline_basis(self: *const Tensor, knots: []const f64, degree: usize, result: *Tensor) !void {
        if (self.shape.len != 1 or result.shape.len != 1 or self.shape != result.shape) {
            return error.ShapeMismatch;
        }
        var i: usize = 0;
        while (i < self.shape) : (i += 1) {
            const x = self.get(&.{ i });
            result.set(&.{ i }, deBoor(x, knots, degree, 0));
        }
    }

    fn deBoor(x: f64, knots: []const f64, degree: usize, i: usize) f64 {
        if (degree == 0) {
            if (i + 1 <= knots.len and x >= knots[i] and x < knots[i + 1]) return 1.0;
            return 0.0;
        }
        const denom_left = knots[i + degree] - knots[i];
        const denom_right = knots[i + degree + 1] - knots[i + 1];
        const a = if (denom_left != 0.0) (x - knots[i]) / denom_left else 0.0;
        const b = if (denom_right != 0.0) (knots[i + degree + 1] - x) / denom_right else 0.0;
        return a * deBoor(x, knots, degree - 1, i) + b * deBoor(x, knots, degree - 1, i + 1);
    }

    pub fn lorenz_embedding(self: *const Tensor, sigma: f64, rho: f64, beta: f64, dt: f64, steps: usize, allocator: Allocator) !Tensor {
        _ = sigma;
        _ = rho;
        _ = beta;
        if (self.shape.len != 1) return error.ShapeMismatch;

        var state = try Tensor.init(allocator, &[_]usize{ 3 }, .f64);
        defer state.deinit();
        state.set(&.{ 0 }, 0.1);
        state.set(&.{ 1 }, 1.0);
        state.set(&.{ 2 }, 1.05);

        var trajectory = std.ArrayList(Tensor).init(allocator);
        defer {
            for (trajectory.items) |*t| t.deinit();
            trajectory.deinit();
        }

        var s: usize = 0;
        while (s < steps) : (s += 1) {
            const x = state.get(&.{ 0 });
            const y = state.get(&.{ 1 });
            const z = state.get(&.{ 2 });
            const dx = sigma * (y - x);
            const dy = x * (rho - z) - y;
            const dz = x * y - beta * z;
            state.set(&.{ 0 }, x + dt * dx);
            state.set(&.{ 1 }, y + dt * dy);
            state.set(&.{ 2 }, z + dt * dz);
            var step_tensor = try state.clone(allocator);
            try trajectory.append(step_tensor);
        }

        var embedded = try Tensor.init(allocator, &[_]usize{ self.shape, 3 * steps }, .f64);
        var i: usize = 0;
        while (i < self.shape) : (i += 1) {
            const input_val = self.get(&.{ i });
            var eidx: usize = 0;
            var t: usize = 0;
            while (t < steps) : (t += 1) {
                const xt = trajectory.items[t].get(&.{ 0 });
                const yt = trajectory.items[t].get(&.{ 1 });
                const zt = trajectory.items[t].get(&.{ 2 });
                embedded.set(&.{ i, eidx }, input_val * xt); eidx += 1;
                embedded.set(&.{ i, eidx }, yt); eidx += 1;
                embedded.set(&.{ i, eidx }, zt); eidx += 1;
            }
        }
        return embedded;
    }

    pub fn tgn_update(self: *const Tensor, edge_features: *const Tensor, node_features: *const Tensor, time_encoding: *const Tensor, allocator: Allocator) !Tensor {
        _ = node_features;
        if (self.shape.len != 2) return error.ShapeMismatch;
        var updated = try Tensor.init(allocator, self.shape, .f64);
        std.mem.copy(f64, updated.data, self.data);

        const num_nodes = self.shape;
        const feat_dim = self.shape;[1]
        const num_edges = edge_features.shape;

        var node: usize = 0;
        while (node < num_nodes) : (node += 1) {
            var agg: f64 = 0.0;
            var e: usize = 0;
            while (e < num_edges) : (e += 1) {
                agg += edge_features.get(&.{ e, 0 });
            }
            const denom = if (num_edges > 0) @as(f64, @floatFromInt(num_edges)) else 1.0;
            agg /= denom;

            var d: usize = 0;
            while (d < feat_dim) : (d += 1) {
                const old_feat = self.get(&.{ node, d });
                const time_factor = time_encoding.get(&.{ node });
                updated.set(&.{ node, d }, old_feat + agg * time_factor);
            }
        }
        return updated;
    }

    pub fn ssm_s4d_update(self: *const Tensor, A: *const Tensor, B: *const Tensor, C: *const Tensor, Delta: *const Tensor, u: *const Tensor, dt: f64, allocator: Allocator) !Tensor {
        _ = dt;
        if (self.shape.len != 1) return error.ShapeMismatch;
        const state_dim = self.shape;
        if (u.shape.len != 1) return error.ShapeMismatch;
        const seq_len = u.shape;

        var h = try self.clone(allocator);
        defer h.deinit();

        var y = try Tensor.init(allocator, &[_]usize{ seq_len }, .f64);

        var t: usize = 0;
        while (t < seq_len) : (t += 1) {
            var h_new = try Tensor.init(allocator, &[_]usize{ state_dim }, .f64);
            var i: usize = 0;
            while (i < state_dim) : (i += 1) {
                const a_i = A.get(&.{ i });
                const h_i = h.get(&.{ i });
                const b_i = B.get(&.{ i });
                const delta_i = Delta.get(&.{ i });
                const u_t = u.get(&.{ t });
                const term1 = math.exp(a_i) * h_i;
                const term2 = b_i * delta_i * u_t;
                h_new.set(&.{ i }, term1 + term2);
            }
            h.deinit();
            h = h_new;

            var y_t: f64 = 0.0;
            var s: usize = 0;
            while (s < state_dim) : (s += 1) {
                y_t += C.get(&.{ s }) * h.get(&.{ s });
            }
            y.set(&.{ t }, y_t);
        }
        return y;
    }

    pub fn hyena_conv(self: *const Tensor, filter: *const Tensor, bias: *const Tensor, seq_len: usize, allocator: Allocator) !Tensor {
        if (self.shape.len != 2) return error.ShapeMismatch;
        const T = self.shape;
        const D = self.shape;[1]
        if (seq_len != T) return error.ShapeMismatch;
        if (filter.shape.len != 1 or filter.shape != D) return error.ShapeMismatch;
        if (bias.shape.len != 1 or bias.shape < 1) return error.ShapeMismatch;

        var result = try Tensor.init(allocator, &[_]usize{ T, 1 }, .f64);
        var t: usize = 0;
        while (t < T) : (t += 1) {
            var conv_val: f64 = 0.0;
            var d: usize = 0;
            while (d < D) : (d += 1) {
                conv_val += self.get(&.{ t, d }) * filter.get(&.{ d });
            }
            result.set(&.{ t, 0 }, conv_val + bias.get(&.{ 0 }));
        }
        return result;
    }

    pub fn mamba2_scan(self: *const Tensor, A_log: *const Tensor, B: *const Tensor, C: *const Tensor, Delta: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 1) return error.ShapeMismatch;
        const seq_len = self.shape;
        const d_state = A_log.shape;

        var h = try Tensor.init(allocator, &[_]usize{ d_state }, .f64);
        std.mem.set(f64, h.data, 0.0);

        var y = try Tensor.init(allocator, &[_]usize{ seq_len }, .f64);

        var t: usize = 0;
        while (t < seq_len) : (t += 1) {
            const x_t = self.get(&.{ t });
            var dh = try Tensor.init(allocator, &[_]usize{ d_state }, .f64);
            var s: usize = 0;
            while (s < d_state) : (s += 1) {
                const b_s = B.get(&.{ t, s });
                const h_s = h.get(&.{ s });
                const delta_s = math.exp(Delta.get(&.{ s }));
                const term = (x_t * b_s - h_s) * delta_s;
                dh.set(&.{ s }, term);
            }
            // h = h + dh
            var s2: usize = 0;
            while (s2 < d_state) : (s2 += 1) {
                h.data[s2] += dh.data[s2];
            }

            var y_t: f64 = 0.0;
            var s3: usize = 0;
            while (s3 < d_state) : (s3 += 1) {
                y_t += C.get(&.{ t, s3 }) * h.get(&.{ s3 });
            }
            y.set(&.{ t }, y_t);

            dh.deinit();
        }

        h.deinit();
        return y;
    }
};

test "tensor init and basic ops" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const shape = &[_]usize{ 2, 3 };
    var tensor = try Tensor.init(allocator, shape, .f64);
    defer tensor.deinit();
    tensor.set(&.{ 0, 0 }, 1.0);
    tensor.set(&.{ 1, 2 }, 6.0);
    try testing.expectEqual(@as(f64, 1.0), tensor.get(&.{ 0, 0 }));
}

test "matmul" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const shape_a = &[_]usize{ 2, 3 };
    const shape_b = &[_]usize{ 3, 4 };
    const shape_c = &[_]usize{ 2, 4 };
    var a = try Tensor.init(allocator, shape_a, .f64);
    defer a.deinit();
    var b = try Tensor.init(allocator, shape_b, .f64);
    defer b.deinit();
    var c = try Tensor.init(allocator, shape_c, .f64);
    defer c.deinit();
    a.set(&.{ 0, 0 }, 1.0); a.set(&.{ 0, 1 }, 2.0); a.set(&.{ 0, 2 }, 3.0);
    a.set(&.{ 1, 0 }, 4.0); a.set(&.{ 1, 1 }, 5.0); a.set(&.{ 1, 2 }, 6.0);
    b.set(&.{ 0, 0 }, 7.0);  b.set(&.{ 0, 1 }, 8.0);  b.set(&.{ 0, 2 }, 9.0);  b.set(&.{ 0, 3 }, 10.0);
    b.set(&.{ 1, 0 }, 11.0); b.set(&.{ 1, 1 }, 12.0); b.set(&.{ 1, 2 }, 13.0); b.set(&.{ 1, 3 }, 14.0);
    b.set(&.{ 2, 0 }, 15.0); b.set(&.{ 2, 1 }, 16.0); b.set(&.{ 2, 2 }, 17.0); b.set(&.{ 2, 3 }, 18.0);
    try a.matmul(&b, &c);
    // Expected:
    // [ [ 74, 80, 86, 92 ],
    //   [ 173, 188, 203, 218 ] ]
    try testing.expectEqual(@as(f64, 74.0), c.get(&.{ 0, 0 }));
    try testing.expectEqual(@as(f64, 80.0), c.get(&.{ 0, 1 }));
    try testing.expectEqual(@as(f64, 173.0), c.get(&.{ 1, 0 }));
    try testing.expectEqual(@as(f64, 188.0), c.get(&.{ 1, 1 }));
}

test "conv2d basic" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const shape_in = &[_]usize{ 1, 1, 5, 5 };
    const shape_k = &[_]usize{ 1, 1, 3, 3 };
    var input = try Tensor.init(allocator, shape_in, .f64);
    defer input.deinit();
    var kernel = try Tensor.init(allocator, shape_k, .f64);
    defer kernel.deinit();
    for (0..25) |i| {
        input.set(&.{ 0, 0, @intCast(i / 5), @intCast(i % 5) }, @as(f64, @floatFromInt(i + 1)));
    }
    for (0..9) |i| {
        kernel.set(&.{ 0, 0, @intCast(i / 3), @intCast(i % 3) }, 1.0);
    }
    var out = try input.conv2d(&kernel, 0, 1, allocator);
    defer out.deinit();
    // Top-left 3x3 sum: 1+2+3+6+7+8+11+12+13 = 63
    try testing.expectEqual(@as(f64, 63.0), out.get(&.{ 0, 0, 0, 0 }));
}

