test "softmax" {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const shape = &[_]usize{ 3 };
    var input = try Tensor.init(allocator, shape, .f64);
    defer input.deinit();
    var output = try Tensor.init(allocator, shape, .f64);
    defer output.deinit();
    input.set(&.{ 0 }, 1.0);
    input.set(&.{ 1 }, 2.0);
    input.set(&.{ 2 }, 3.0);
    try input.softmax(0, &output);
    const e1 = math.exp(1.0); const e2 = math.exp(2.0); const e3 = math.exp(3.0);
    const sum = e1 + e2 + e3;
    try testing.expectApproxEqAbs(e1 / sum, output.get(&.{ 0 }), 1e-9);
    try testing.expectApproxEqAbs(e3 / sum, output.get(&.{ 2 }), 1e-9);
}

